#!/usr/bin/env python3
"""One offline recognition job; input/output paths are generated by the server."""
import argparse
import json
import os
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / 'software'))
from mack.offline import deny_network

os.environ.update(HF_HUB_OFFLINE='1', TRANSFORMERS_OFFLINE='1', HF_HUB_DISABLE_TELEMETRY='1', DO_NOT_TRACK='1')
deny_network()


def main():
    parser = argparse.ArgumentParser()
    for name in ('config', 'audio', 'output'):
        parser.add_argument('--'+name, type=Path, required=True)
    args = parser.parse_args()
    from importlib.metadata import version
    if version('mlx-audio') != '0.6.1':
        raise ValueError('Use the pinned MLX Audio environment.')
    import soundfile as sf
    from mlx_audio.stt import load
    config = json.loads(args.config.read_text())
    audio, rate = sf.read(args.audio, dtype='float32')
    if rate != 16000 or audio.ndim != 1:
        raise ValueError('Expected mono 16 kHz audio.')
    model = load(config['model_path'])
    result = model.generate(audio, language='English', max_tokens=512, temperature=0.0, verbose=False)
    args.output.write_text(json.dumps({'text': result.text, 'truncated': result.generation_tokens >= 512}))
    args.output.chmod(0o600)


if __name__ == '__main__':
    main()
